function isPrime(n) {
  // 1 is not a prime number
  if (n === 1) {
    return false;
  }

  // 2 and 3 are prime numbers
  if (n === 2 || n === 3) {
    return true;
  }

  // Even numbers are not prime
  if (n % 2 === 0) {
    return false;
  }

  // Check odd numbers up to the square root of n
  for (let I = 3; I <= Math.sqrt(n); I += 2) {
    if (n % I === 0) {
