#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

using namespace std;

int countWordOccurrences(string word, string filename) {
    int count = 0;
    ifstream file(filename);
    if (!file.is_open()) {
        cerr << "Error opening file: " << filename << endl;
        return -1;
    }

    string line;
    while (getline(file, line)) {
        transform(line.begin(), line.end(), line.begin(), ::tolower); // convert line to lowercase
        size_t pos = 0;
        while ((pos = line.find(word, pos)) != string::npos) {
            count++;
            pos += word.length();
        }
    }

    file.close();
    return count;
}

int main() {
